import java.nio.charset.StandardCharsets;
public class Main {
    static class Learner { private final String name; Learner(String name) { this.name = name; } String greet() { return "Hello, " + name; } }
    public static void main(String[] args) throws Exception {
        String text = new String(System.in.readAllBytes(), StandardCharsets.UTF_8).trim();
        String[] names = text.split("\s+");
        if (text.isEmpty() || names.length != 2) { System.exit(1); return; }
        Learner first = new Learner(names[0]);
        Learner second = new Learner(names[1]);
        System.out.println(first.greet());
        System.out.println(second.greet());
    }
}
